import{_ as t,o as i,c as n,ag as s}from"./chunks/framework.DNmTgtHf.js";const g=JSON.parse('{"title":"Dependency Inversion (DIP) vs. Dependency Injection (DI) — the details","description":"","frontmatter":{},"headers":[],"relativePath":"design_patterns/foundations/dip_vs_di/DipVsDi.md","filePath":"design_patterns/foundations/dip_vs_di/DipVsDi.md"}'),a={name:"design_patterns/foundations/dip_vs_di/DipVsDi.md"};function o(r,e,d,l,c,h){return i(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="dependency-inversion-dip-vs-dependency-injection-di-—-the-details" tabindex="-1">Dependency Inversion (DIP) vs. Dependency Injection (DI) — the details <a class="header-anchor" href="#dependency-inversion-dip-vs-dependency-injection-di-—-the-details" aria-label="Permalink to &quot;Dependency Inversion (DIP) vs. Dependency Injection (DI) — the details&quot;">​</a></h1><blockquote><p>Two ideas that constantly get conflated. They are <strong>related but distinct</strong>, and you can have one without the other. Both are central to almost every pattern that enables testing and substitution.</p></blockquote><hr><h2 id="dependency-inversion-principle-dip-—-the-principle" tabindex="-1">Dependency Inversion Principle (DIP) — the <strong>principle</strong> <a class="header-anchor" href="#dependency-inversion-principle-dip-—-the-principle" aria-label="Permalink to &quot;Dependency Inversion Principle (DIP) — the **principle**&quot;">​</a></h2><p>The &quot;D&quot; of SOLID. Two clauses, in Robert C. Martin&#39;s original phrasing:</p><ol><li><strong>High-level modules should not depend on low-level modules.</strong> Both should depend on <strong>abstractions</strong>.</li><li><strong>Abstractions should not depend on details.</strong> Details should depend on abstractions.</li></ol><p>Plainer phrasing: <em>don&#39;t let your important code (orchestrators, business logic) reach down to depend on specific implementations. Have both depend on an interface in the middle.</em></p><h3 id="what-inversion-means-—-the-arrow-flip" tabindex="-1">What &quot;inversion&quot; means — the arrow flip <a class="header-anchor" href="#what-inversion-means-—-the-arrow-flip" aria-label="Permalink to &quot;What &quot;inversion&quot; means — the arrow flip&quot;">​</a></h3><p>In naive OOP, dependency arrows run &quot;downhill&quot; from high-level → low-level:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HR ──▶ AndroidHiringProcess</span></span>
<span class="line"><span>HR ──▶ BackendHiringProcess          (HR is locked to specific concrete classes)</span></span>
<span class="line"><span>HR ──▶ IosHiringProcess</span></span></code></pre></div><p>DIP says: introduce an abstraction in the middle and <strong>flip the bottom arrow</strong> so concrete classes point <em>up</em> at the abstraction:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                   HiringProcess (interface)</span></span>
<span class="line"><span>                   ▲       ▲</span></span>
<span class="line"><span>                   │       └── implements ── AndroidHiringProcess, BackendHiringProcess, ...</span></span>
<span class="line"><span>HR ──── depends on ┘</span></span></code></pre></div><p>Both ends point at the same abstraction. High-level code no longer reaches <em>down</em> at low-level details; details point <em>up</em> at a stable abstraction. That arrow flip is the &quot;inversion.&quot;</p><h3 id="where-dip-lives-in-the-production-factory-method-code" tabindex="-1">Where DIP lives in the production factory_method code <a class="header-anchor" href="#where-dip-lives-in-the-production-factory-method-code" aria-label="Permalink to &quot;Where DIP lives in the production factory_method code&quot;">​</a></h3><p>Exactly here:</p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// HR.java (production variant)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">private</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> final</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> HiringProcess hiringProcess;   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ← interface, not the concrete abstract class</span></span></code></pre></div><p>If this were <code>private final DeveloperHiringProcess hiringProcess;</code> (as in the <em>learning</em> variant), DIP would be partially violated — HR would be locked to the developer branch even though <code>DeveloperHiringProcess</code> is itself an abstract class. The interface above is the <em>most abstract</em> suitable type for HR&#39;s role; depending on it, not the abstract class, is what makes the dependency DIP-clean.</p><hr><h2 id="dependency-injection-di-—-the-technique" tabindex="-1">Dependency Injection (DI) — the <strong>technique</strong> <a class="header-anchor" href="#dependency-injection-di-—-the-technique" aria-label="Permalink to &quot;Dependency Injection (DI) — the **technique**&quot;">​</a></h2><p>A technique for <em>how</em> a class receives its dependencies — push them in from outside, instead of constructing them internally. Three common flavours in Java:</p><table tabindex="0"><thead><tr><th>Flavour</th><th>What it looks like</th><th>When to use</th></tr></thead><tbody><tr><td><strong>Constructor injection</strong></td><td><code>HR(HiringProcess hp) { this.hp = hp; }</code></td><td>Default. Fields can be <code>final</code>; dependencies guaranteed at construction.</td></tr><tr><td><strong>Setter injection</strong></td><td><code>void setProcess(HiringProcess hp)</code></td><td>Optional dependencies, or when breaking circular dependencies.</td></tr><tr><td><strong>Field injection</strong></td><td><code>@Autowired HiringProcess hp;</code> (Spring)</td><td>Convenient but harder to test, fields cannot be <code>final</code>, dependencies hidden — usually avoided in modern style.</td></tr></tbody></table><p>DI is <strong>just the mechanic</strong> of pushing dependencies in. It says nothing about whether what gets pushed in is an abstraction or a concretion.</p><hr><h2 id="dip-vs-di-—-they-are-not-the-same-thing" tabindex="-1">DIP vs DI — they are not the same thing <a class="header-anchor" href="#dip-vs-di-—-they-are-not-the-same-thing" aria-label="Permalink to &quot;DIP vs DI — they are not the same thing&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Question</th><th>DIP</th><th>DI</th></tr></thead><tbody><tr><td>What is it?</td><td>A <strong>principle</strong></td><td>A <strong>technique</strong></td></tr><tr><td>What does it govern?</td><td><em>What</em> you depend on (abstraction vs. concretion)</td><td><em>How</em> the dependency arrives</td></tr><tr><td>Where does it live?</td><td>In <strong>type signatures</strong> of fields / parameters</td><td>In <strong>construction</strong> code</td></tr><tr><td>Can you have one without the other?</td><td><strong>Yes</strong> — see matrix below</td><td><strong>Yes</strong></td></tr></tbody></table><h3 id="the-four-combinations" tabindex="-1">The four combinations <a class="header-anchor" href="#the-four-combinations" aria-label="Permalink to &quot;The four combinations&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>DI ✓</th><th>DI ✗</th></tr></thead><tbody><tr><td><strong>DIP ✓</strong></td><td><strong>Best practice.</strong> HR receives a <code>HiringProcess</code> interface in its constructor.</td><td>Rare. HR holds an interface field but constructs the implementation internally (reflection, service locator). DIP honoured but no testability win from DI.</td></tr><tr><td><strong>DIP ✗</strong></td><td><strong>The subtle trap.</strong> HR gets injected, but the parameter type is concrete. <em>&quot;I&#39;m using DI&quot;</em> — yet the code still couples to a specific implementation.</td><td>The classic mess. HR does <code>new AndroidHiringProcess()</code> inside its own constructor.</td></tr></tbody></table><p>The bottom-right (neither) is where most legacy code lives. The top-left (both) is where you want to be.</p><hr><h2 id="how-to-spot-violations" tabindex="-1">How to spot violations <a class="header-anchor" href="#how-to-spot-violations" aria-label="Permalink to &quot;How to spot violations&quot;">​</a></h2><p><strong>DIP violations:</strong></p><ul><li>A high-level class names a concrete class in a field, parameter, or return type.</li><li>The class can&#39;t be unit-tested without spinning up real low-level dependencies.</li><li>Adding a new variant of a low-level component requires editing high-level code.</li></ul><p><strong>DI without DIP (the trap):</strong></p><ul><li>A class accepts a dependency via its constructor (DI ✓) but the parameter type is concrete.</li><li><em>&quot;I&#39;m using DI&quot;</em> feels true, yet the type signature still couples high-level to low-level.</li><li>Easy fix: change the parameter type from <code>ConcreteClass</code> to <code>AnInterface</code>.</li></ul><p><strong>DIP without DI (rare):</strong></p><ul><li>Code holds an interface field but constructs the implementation internally via <code>new</code> or a static lookup.</li><li>Principle honoured (field type), testability lost (no seam to inject a mock).</li></ul><hr><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><blockquote><p><strong>DIP says:</strong> <em>depend on abstractions, not concretions.</em><strong>DI says:</strong> <em>don&#39;t construct your dependencies — receive them.</em></p><p>They reinforce each other in modern code, but answer different questions: DIP is <em>what type</em>, DI is <em>how it arrives</em>. In casual talk it doesn&#39;t matter; in design discussions, the distinction avoids bad refactors.</p></blockquote><hr><h2 id="di-in-practice-—-read-this-before-the-pattern-selection-exercise" tabindex="-1">DI in practice — read this before the Pattern Selection Exercise <a class="header-anchor" href="#di-in-practice-—-read-this-before-the-pattern-selection-exercise" aria-label="Permalink to &quot;DI in practice — read this before the Pattern Selection Exercise&quot;">​</a></h2><h3 id="the-pain-di-relieves" tabindex="-1">The pain DI relieves <a class="header-anchor" href="#the-pain-di-relieves" aria-label="Permalink to &quot;The pain DI relieves&quot;">​</a></h3><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Hardcoded — class welds itself to a concrete implementation:</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">public</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> class</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> SignupService</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  private</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> final</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> EmailSender sender </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> EmailSender</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Injected — collaborator passed in from outside:</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">public</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> class</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> SignupService</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  private</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> final</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> EmailSender sender;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  public</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> SignupService</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(EmailSender </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">sender</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    this</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.sender </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> sender;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>When a class news-up its own collaborators, you can&#39;t:</p><ul><li>Replace the real implementation in tests (no place to inject a mock).</li><li>Swap implementations per environment (dev vs prod, local SMTP vs SES).</li><li>Configure the dependency from outside (timeouts, URLs, retries).</li><li>Reuse the class with a different collaborator.</li></ul><p>DI moves construction out of the using class into a separate <strong>wiring layer</strong> — either explicit setup in <code>main()</code> (manual DI) or a container like Spring.</p><h3 id="why-constructor-injection-wins-over-the-other-flavours" tabindex="-1">Why constructor injection wins over the other flavours <a class="header-anchor" href="#why-constructor-injection-wins-over-the-other-flavours" aria-label="Permalink to &quot;Why constructor injection wins over the other flavours&quot;">​</a></h3><p>Constructor injection is the modern default — and Spring&#39;s official recommendation since v4 — for these reasons:</p><ol><li><strong>Final fields.</strong> Dependency cannot be reassigned — JMM publication guarantees + thread safety + clear intent.</li><li><strong>No half-initialised objects.</strong> The object cannot even <em>exist</em> without its full set of dependencies.</li><li><strong>Visible dependency list.</strong> The constructor signature is the one place to read what a class needs.</li><li><strong>Testable without a framework.</strong> <code>new SignupService(mockSender)</code> works in any test; no Spring required.</li><li><strong>Spring-agnostic.</strong> The class doesn&#39;t depend on <code>@Autowired</code> or any framework annotation. Spring detects the single constructor automatically.</li></ol><h3 id="autowired-vs-di-—-they-are-at-different-levels" tabindex="-1"><code>@Autowired</code> vs DI — they are at different levels <a class="header-anchor" href="#autowired-vs-di-—-they-are-at-different-levels" aria-label="Permalink to &quot;\`@Autowired\` vs DI — they are at different levels&quot;">​</a></h3><p>A common confusion worth nailing down:</p><table tabindex="0"><thead><tr><th></th><th>DI</th><th><code>@Autowired</code></th></tr></thead><tbody><tr><td>What is it?</td><td>A <strong>technique</strong> — push dependencies in from outside</td><td>A <strong>Spring annotation</strong> that tells the Spring container how to inject a value</td></tr><tr><td>Where does it live?</td><td>Anywhere — plain Java, manual <code>main()</code> wiring, or any framework</td><td>Only in Spring (and Spring-compatible) projects</td></tr><tr><td>Is one necessary for the other?</td><td>No. You can do DI with no annotations at all (manual DI).</td><td><code>@Autowired</code> is one <em>implementation</em> of DI — Spring&#39;s.</td></tr></tbody></table><p>Three subtleties about <code>@Autowired</code> worth knowing:</p><ol><li><p><strong>Modern Spring (4.3+) auto-injects a single constructor.</strong> No annotation needed:</p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">@</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Service</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">public</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> class</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> SignupService</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  private</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> final</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> EmailSender sender;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  public</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> SignupService</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(EmailSender </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">sender</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">this</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.sender </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> sender; }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// No @Autowired anywhere. Spring detects the single constructor and uses it.</span></span></code></pre></div><p>Adding <code>@Autowired</code> here is redundant. Older Spring code carries it as habit; new code should drop it.</p></li><li><p><strong><code>@Autowired</code> on a field = field injection (avoid).</strong></p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">@</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Service</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">public</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> class</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> SignupService</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  @</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Autowired</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> private</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> EmailSender sender;   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// field injection</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>The downsides: cannot make the field <code>final</code>; dependencies hidden from constructor signature; only constructible via Spring, i.e. impossible to unit-test without the framework. Tolerated historically; avoid in new code.</p></li><li><p><strong><code>@Autowired</code> on a setter = setter injection (rare).</strong> Used for genuinely optional dependencies or to break circular dependencies. Modern code expresses optional dependencies as <code>Optional&lt;Foo&gt;</code> constructor parameters or with <code>@Nullable</code>, not as setters.</p></li></ol><p><strong>Bottom line:</strong> in modern Spring, prefer constructor injection with no <code>@Autowired</code> annotation at all. The constructor itself is the DI mechanism; the annotation is a Spring-internal hint that&#39;s no longer needed.</p><h3 id="inversion-of-control-—-the-broader-principle-di-is-a-special-case-of" tabindex="-1">Inversion of Control — the broader principle DI is a special case of <a class="header-anchor" href="#inversion-of-control-—-the-broader-principle-di-is-a-special-case-of" aria-label="Permalink to &quot;Inversion of Control — the broader principle DI is a special case of&quot;">​</a></h3><p>DI is a specific case of <strong>Inversion of Control (IoC)</strong>: instead of a class controlling how its dependencies arrive, something else (the caller, a container) controls it. Hollywood Principle: <em>&quot;Don&#39;t call us, we&#39;ll call you.&quot;</em></p><p>IoC shows up beyond construction too — the JVM calling <code>main()</code>, Spring calling <code>@PostConstruct</code>, JUnit calling <code>@Test</code> methods. DI is the <em>construction-time</em> face of IoC.</p><h3 id="how-di-relates-to-the-other-creational-patterns" tabindex="-1">How DI relates to the other creational patterns <a class="header-anchor" href="#how-di-relates-to-the-other-creational-patterns" aria-label="Permalink to &quot;How DI relates to the other creational patterns&quot;">​</a></h3><p>Once DI is in your codebase, several patterns from this repo shift in role:</p><table tabindex="0"><thead><tr><th>Pattern</th><th>What DI does to it</th></tr></thead><tbody><tr><td><strong>Singleton</strong></td><td>Spring beans default to <strong>singleton scope</strong> — the container is your singleton manager. <code>getInstance()</code>, double-checked locking, Bill Pugh holders all become unnecessary in a Spring app. Your Singleton implementations remain <em>correct</em>; they just become <em>unneeded</em> once Spring is wiring things.</td></tr><tr><td><strong>Factory Method</strong></td><td>Subsumed when the factory exists <em>only</em> to hand callers an instance. The container constructs and injects. Factories survive when they make non-trivial <strong>runtime</strong> choices (pick a strategy by input not known at wiring time).</td></tr><tr><td><strong>Builder</strong></td><td>Orthogonal — both coexist. DI gives you long-lived <strong>collaborators</strong>; Builder constructs short-lived <strong>values</strong>. A <code>JobOffer</code> is built per request; the <code>EmailSender</code> that delivers it is wired once at startup.</td></tr><tr><td><strong>Static factory methods (EJ Item 1)</strong></td><td>Spring&#39;s <code>@Bean</code> methods inside <code>@Configuration</code> classes <em>are</em> static factory methods. Side Quest A pays off here.</td></tr></tbody></table><h3 id="spring-s-role-beyond-manual-di" tabindex="-1">Spring&#39;s role beyond manual DI <a class="header-anchor" href="#spring-s-role-beyond-manual-di" aria-label="Permalink to &quot;Spring&#39;s role beyond manual DI&quot;">​</a></h3><p>Spring is a <strong>DI container</strong>. You annotate classes (<code>@Service</code>, <code>@Component</code>, <code>@Repository</code>, <code>@Controller</code>, or <code>@Configuration</code> + <code>@Bean</code>); Spring scans them at startup, builds the dependency graph, and instantiates everything in the right order.</p><p>Three things Spring adds beyond manual DI:</p><ol><li><strong>Automatic graph construction.</strong> No hand-written <code>main()</code> wiring code; component scanning does it.</li><li><strong>Bean scopes.</strong> <code>singleton</code> (default — one per container), <code>prototype</code> (new instance per injection), <code>request</code> / <code>session</code> for web apps.</li><li><strong>Lifecycle hooks.</strong> <code>@PostConstruct</code>, <code>@PreDestroy</code>, <code>ApplicationContextAware</code>, etc.</li></ol><h3 id="why-manual-di-first-then-spring-is-the-recommended-order" tabindex="-1">Why &quot;manual DI first, then Spring&quot; is the recommended order <a class="header-anchor" href="#why-manual-di-first-then-spring-is-the-recommended-order" aria-label="Permalink to &quot;Why &quot;manual DI first, then Spring&quot; is the recommended order&quot;">​</a></h3><p>Two passes that teach different things:</p><ul><li><strong>Manual DI in plain <code>main()</code></strong> teaches that DI is <em>just constructor parameters</em>. No magic. Feel the pain when the graph gets bigger than five classes — you&#39;re typing <code>new</code> for every node.</li><li><strong>Spring</strong> teaches that the container <em>is</em> automation of the manual setup, plus scopes and lifecycle. Without doing manual DI first, Spring feels mysterious; afterwards, it feels like exactly what you&#39;d build if you did the manual version a hundred times.</li></ul><p>Skipping manual DI and going straight to Spring is the most common reason developers cargo-cult <code>@Autowired</code> everywhere without understanding what the annotation actually does.</p><hr><h2 id="concept-check-questions-to-answer-before-coding" tabindex="-1">Concept-check questions to answer before coding <a class="header-anchor" href="#concept-check-questions-to-answer-before-coding" aria-label="Permalink to &quot;Concept-check questions to answer before coding&quot;">​</a></h2><ol><li>In <code>creational/factory/factory_method/</code>, <code>HR</code> already takes a <code>HiringProcess</code> in its constructor. So <code>HR</code> is <em>already</em> using DI. What about <code>EmailService</code> and <code>OfferLetterService</code> — are they DI-friendly too? What signal in <code>DeveloperHiringProcess</code>&#39;s constructor tells you the answer?</li><li>Spring beans default to singleton scope. If <code>EmailService</code> is a Spring bean and <code>AndroidHiringProcess</code> and <code>BackendHiringProcess</code> are too, how many <code>EmailService</code> instances does Spring create? What does that imply for <code>EmailService</code>&#39;s thread-safety obligations?</li><li>Suppose you write <code>class HR { private final HiringProcess hp = new AndroidHiringProcess(...); }</code>. List two reasons this is hard to test, and the <em>one</em> small change that fixes both.</li></ol><hr><h2 id="suggested-practice-path-three-stages" tabindex="-1">Suggested practice path (three stages) <a class="header-anchor" href="#suggested-practice-path-three-stages" aria-label="Permalink to &quot;Suggested practice path (three stages)&quot;">​</a></h2><ul><li>[ ] <strong>Stage 1 — Audit pass on <code>factory_method/</code>.</strong> Confirm everything is DI-clean already (most of it is). Identify the wiring code in <code>FactoryMethodRun.main()</code> — that&#39;s literally a manual DI bootstrap.</li><li>[ ] <strong>Stage 2 — Manual DI from scratch in a new package.</strong> Small <code>signup-service</code> style example contrasting &quot;bad&quot; (internal <code>new</code>) with &quot;good&quot; (constructor-injected), with a hand-written <code>main()</code> doing the wiring. Feel the typing as the graph grows.</li><li>[ ] <strong>Stage 3 — Spring layer on top.</strong> Add <code>@Service</code> / <code>@Component</code> annotations, an <code>@SpringBootApplication</code> entry point, watch the wiring code disappear. Demonstrate singleton vs prototype scope side-by-side.</li></ul><hr><h2 id="pointers-in-this-codebase" tabindex="-1">Pointers in this codebase <a class="header-anchor" href="#pointers-in-this-codebase" aria-label="Permalink to &quot;Pointers in this codebase&quot;">​</a></h2><ul><li><code>creational/factory_method/HR.java</code> — DIP applied (field is the <code>HiringProcess</code> interface) + DI applied (constructor injection).</li><li><code>creational/factory_method_basic/HR.java</code> — DIP only partially applied (field is <code>DeveloperHiringProcess</code>, the abstract class — an abstraction, but not the most abstract suitable one) + DI applied. Useful contrast — same DI mechanic, weaker DIP.</li><li><code>creational/Factory.md</code> — discusses the migration that introduced DIP at the HR layer (change #5 in the transition).</li></ul><hr><h2 id="done-when" tabindex="-1">Done when <a class="header-anchor" href="#done-when" aria-label="Permalink to &quot;Done when&quot;">​</a></h2><p>You can answer these three concept-check questions from above without looking:</p><ol><li>In <code>factory_method/</code>, is <code>EmailService</code> DI-friendly? What signal tells you?</li><li>If <code>EmailService</code> is a Spring singleton bean and both hiring-process subclasses hold it, how many <code>EmailService</code> instances exist? What thread-safety does that require?</li><li>Write <code>class HR { private final HiringProcess hp = new AndroidHiringProcess(...); }</code>. Name two testability problems and the one-line fix.</li></ol><hr><h2 id="related-topics" tabindex="-1">Related topics <a class="header-anchor" href="#related-topics" aria-label="Permalink to &quot;Related topics&quot;">​</a></h2><ul><li><strong>SOLID — DIP</strong> — this doc is the deep dive; the SOLID doc has the one-line summary.</li><li><strong>Pattern Selection Exercise</strong> (<code>todo/study_plan/deep_dives/PatternSelectionExercise.md</code>) — Stage 3 of the practice path above is implemented there with Strategy/Registry/DI variants.</li></ul>`,85)])])}const u=t(a,[["render",o]]);export{g as __pageData,u as default};
